cipher_hex = """
    
""".strip()

cipher = bytes.fromhex(cipher_hex)
png_header = bytes.fromhex("89504e470d0a1a0a0000000d49484452")
keystream = bytes(c ^ p for c, p in zip(cipher[:16], png_header))
print("Recovered keystream:", keystream.hex())

plaintext = b""
for i in range(0, len(cipher), 16):
    block = cipher[i:i+16]
    decrypted_block = bytes(c ^ k for c, k in zip(block, keystream))
    plaintext += decrypted_block

with open("recovered_flag.png", "wb") as f:
    f.write(plaintext)
print("Saved as recovered_flag.png")